#!/usr/bin/env node
/**
 * Tests for the parallel lanes of workflows/impl-review-loop.js: with `lanes: true` and independent task groups each lane
 * runs its blocks in its own worktree and one merge gate joins them. The grouping rules are in
 * tools/impl-review-loop-blocks.test.mjs, the merge itself in tools/gate.test.mjs.
 *
 *   node --test tools/impl-review-loop-lanes.test.mjs
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { run, ARGS_M, review, impl, gate, laneGate, reviewLabels } from './impl-review-loop.harness.mjs';

const task = (id, files, dependsOn = []) => ({ id, title: `task-${id}-title`, files, dependsOn, tdd: false, criteria: [] });
const green = () => impl({ gate: gate('green') });
const lanesArgs = (tasks, extra = {}) => ({ ...ARGS_M, verify: 'node --test x', lanes: true, plan: { tasks }, ...extra });
const two = [task('T1', ['src/Orders/OrdersQuery.cs']), task('T2', ['src/Orders/OrdersQuery.cs'], ['T1']), task('T3', ['src/Orders/Dto/']), task('T4', ['src/Orders/Dto/Row.cs'])];
const lanePrompts = (calls) => calls.filter((c) => /^lane/.test(c.opts.label ?? ''));

test('given two independent task groups, when the loop runs with lanes, then both lanes run, one merge gate gets both refs and the final verification follows', async () => {
  // Given
  const args = lanesArgs(two);
  // When
  const { out, calls } = await run(args, [review([]), review([]), review([])], [green(), green()]);
  // Then
  const added = calls.filter((c) => / · add worktree$/.test(c.opts.label ?? ''));
  const merges = calls.filter((c) => c.opts.label === 'lanes · merge');
  assert.equal(added.length, 2);
  assert.ok(added.every((c) => /--lane-add l\d/.test(c.prompt) && c.opts.model === 'haiku' && c.opts.effort === 'low' && !c.opts.agentType));
  const impls = calls.filter((c) => c.opts.agentType === 'implementer');
  assert.deepEqual(impls.map((c) => /--root 'C:\/lanes\/l(\d)'/.exec(c.prompt)?.[1]).sort(), ['1', '2']);
  assert.ok(impls.every((c) => /--no-scope/.test(c.prompt)));
  assert.equal(merges.length, 1);
  assert.match(merges[0].prompt, /--merge deliver-lane\/l1 deliver-lane\/l2/);
  assert.ok(!/--no-scope/.test(merges[0].prompt));
  assert.ok(calls.findIndex((c) => c === merges[0]) < calls.findIndex((c) => reviewLabels([c], 1).length));
  assert.equal(reviewLabels(calls, 1).length, 1);
  assert.equal(out.status, 'OK');
});

test('given lanes that save fewer than two tasks, when the loop runs, then it runs serially', async () => {
  // Given
  const tasks = [task('T1', ['src/Orders/OrdersQuery.cs']), task('T2', ['src/Orders/OrdersQuery.cs'], ['T1']), task('T3', ['src/Orders/OrdersQuery.cs'], ['T2']), task('T4', ['src/Orders/Dto/'])];
  const args = lanesArgs(tasks);
  // When
  const { out, calls } = await run(args, [review([]), review([])], [green()]);
  // Then
  assert.equal(lanePrompts(calls).length, 0);
  assert.equal(calls.filter((c) => c.opts.agentType === 'implementer').length, 1);
  assert.ok(calls.every((c) => !/--no-scope/.test(c.prompt)));
  assert.equal(out.status, 'OK');
});

test('given lanes: true without a verify command, when the loop runs, then it runs serially and says why', async () => {
  // Given
  const args = lanesArgs(two, { verify: undefined });
  // When
  const { out, calls } = await run(args, [review([])], [impl()]);
  // Then
  assert.equal(lanePrompts(calls).length, 0);
  assert.ok(out.gaps.some((g) => /lanes/.test(g)));
});

test('given lanes that are not asked for, when the loop runs, then it runs serially', async () => {
  // Given
  const args = lanesArgs(two, { lanes: undefined });
  // When
  const { calls } = await run(args, [review([]), review([])], [green()]);
  // Then
  assert.equal(lanePrompts(calls).length, 0);
});

test('given a merge gate that reports red: merge, when the loop runs, then it stalls with the conflicting files', async () => {
  // Given
  const conflict = () => ({ gate: laneGate('red: merge', { test: 'merge conflict', outside: ['src/Orders/Dto/Row.cs'] }) });
  const lanes = (prompt, opts) => (/^lane (\d+) /.test(opts.label) ? { line: JSON.stringify({ lane: `l${/\d+/.exec(opts.label)[0]}`, path: `C:/lanes/l${/\d+/.exec(opts.label)[0]}`, branch: `deliver-lane/l${/\d+/.exec(opts.label)[0]}` }) } : conflict());
  // When
  const { out, calls } = await run(lanesArgs(two), [review([]), review([])], [green(), green()], { lanes });
  // Then
  assert.equal(out.status, 'STALL');
  assert.equal(out.stall.why, 'merge-conflict');
  assert.match(out.stall.reason, /src\/Orders\/Dto\/Row\.cs/);
  assert.equal(reviewLabels(calls, 1).length, 0);
});

test('given a lane runner that returns no worktree, when the loop runs, then it stalls before any implementer runs', async () => {
  // Given
  const lanes = () => null;
  // When
  const { out, calls } = await run(lanesArgs(two), [], [], { lanes });
  // Then
  assert.equal(out.status, 'STALL');
  assert.equal(calls.filter((c) => c.opts.agentType === 'implementer').length, 0);
});
